from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime
from typing import Any

from packaging.specifiers import InvalidSpecifier, SpecifierSet
from packaging.version import InvalidVersion, Version


def _parse_datetime(raw: Any) -> datetime | None:
    """Parse an ISO 8601 timestamp, returning ``None`` if it can't be parsed."""
    if not isinstance(raw, str) or not raw:
        return None
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        return None


@dataclass(frozen=True)
class Release:
    """A single package release (one version), aggregated across its distributions."""

    upload_time: datetime
    yanked: bool
    requires_python: SpecifierSet | None

    @classmethod
    def from_distributions(cls, distributions: list[dict[str, Any]]) -> Release | None:
        """Build a ``Release`` from a list of distribution dicts.

        Returns ``None`` if no distribution has a parseable ``upload_time_iso_8601`` field.
        """
        upload_times = [
            dt
            for d in distributions
            if (dt := _parse_datetime(d.get("upload_time_iso_8601"))) is not None
        ]
        if not upload_times:
            return None

        # A release is yanked only if every one of its distributions is yanked.
        yanked = all(bool(d.get("yanked", False)) for d in distributions)

        # Use the first non-empty, valid ``requires_python`` field across distributions.
        requires_python: SpecifierSet | None = None
        for d in distributions:
            raw = d.get("requires_python")
            if not raw:
                continue
            try:
                requires_python = SpecifierSet(raw)
                break
            except InvalidSpecifier:
                continue

        return cls(
            upload_time=min(upload_times),
            yanked=yanked,
            requires_python=requires_python,
        )


@dataclass
class Package:
    """A PyPI package and its releases."""

    name: str
    releases: dict[Version, Release] = field(default_factory=dict)

    @classmethod
    def from_json(cls, data: dict[str, Any]) -> Package:
        """Parse a PyPI JSON API response into a ``Package``.

        Releases are dropped when they have no distributions, when no distribution has a
        parseable ``upload_time_iso_8601`` field, or when the version string is not a valid
        PEP 440 version.
        """
        info = data.get("info") or {}
        name = info.get("name", "")

        releases: dict[Version, Release] = {}
        for version_str, distributions in (data.get("releases") or {}).items():
            if not distributions:
                continue
            try:
                version = Version(version_str)
            except InvalidVersion:
                continue
            release = Release.from_distributions(distributions)
            if release is None:
                continue
            releases[version] = release

        return cls(name=name, releases=releases)

    @property
    def versions(self) -> tuple[Version, ...]:
        """All valid release versions, sorted in ascending order."""
        return tuple(sorted(self.releases))

    @property
    def latest_version(self) -> Version | None:
        """The highest stable, non-yanked version, or ``None`` if none exists."""
        stable = [
            v
            for v in self.versions
            if not v.is_prerelease and not v.is_devrelease and not self.releases[v].yanked
        ]
        return stable[-1] if stable else None

    def get_release(self, version: str | Version) -> Release | None:
        """Return the ``Release`` for ``version``, or ``None`` if there is no such release."""
        if isinstance(version, str):
            try:
                version = Version(version)
            except InvalidVersion:
                return None
        return self.releases.get(version)
